}

fn serve_retained_training_fixture(
    mut channel: HostAuthorityPeerChannel,
    context: OriginalCellQ24TrainingCommandContextV1,
    receipt: codex_hepta_learning_artifacts::LearningIterationReceiptV1,
    signature: codex_hepta_learning_ledger::SignedLearningEvidenceV1,
) -> anyhow::Result<std::thread::JoinHandle<anyhow::Result<usize>>> {
    let binding = context.binding()?;
    let server = std::thread::spawn(move || -> anyhow::Result<usize> {
        let mut next = 1;
        loop {
            let observed = channel.exchange(|bytes| {
                let request: wire::Request = serde_json::from_slice(bytes)
                    .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                request
                    .require_context(&context, binding, next)
                    .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                if request.action != wire::Action::Readback || next > 64 {
                    return Err(HostIssuerTransportError::InvalidRequest);
                }
                let result = wire::encode_completed(
                    &context,
                    receipt.clone(),
                    signature.clone(),
                    super::super::now().map_err(|_| HostIssuerTransportError::InvalidRequest)?,
                )
                .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                let response = wire::Response::from_request(&request, result);
                next += 1;
                serde_json::to_vec(&response).map_err(|_| HostIssuerTransportError::InvalidRequest)
            })?;
            if !observed {
                return Ok((next - 1) as usize);
            }
        }
    });
    Ok(server)
}

// This method is compiled only through serving::command_test_support. It is
// a single synchronous observation of the already held original Stage, not
// a command, a new connection, or a receipt/signing-custody constructor.
impl<TW: AnchorWitnessStore + Send + 'static, RW: AnchorWitnessStore + Send + 'static>
    OriginalCellQ24TrainingCommandOwnerV1<TW, RW>
{
    pub(crate) fn fixture_completed_candidate_receipt(
        &self,
    ) -> Result<Option<OriginalCellQ24TrainingCommandReceiptV1>, super::Error> {
        use codex_hepta_intelligence_eval::ProductEvaluationExecutionStoreErrorV1 as Store;
        use crate::CellQ24TrainingOwnerErrorV1 as Native;
        use crate::OriginalCellQ24TrainingReceiptErrorV1 as Receipt;
        use crate::OriginalCellQ24TrainingStageErrorV1 as Stage;
        use crate::learning_owner_journal::LearningOriginalOwnerErrorV1 as Owner;

        let material = match crate::SourceBoundCellQ24TrainingStageV1::read_candidate_material(
            &self.stage,
            &self.context.dataset,
        ) {
            Ok(material) => material,
            // Exactly the non-completed states already distinguished by the
            // original command service. No other read failure becomes None.
            Err(Stage::Busy)
            | Err(Stage::Training(Native::Pending))
            | Err(Stage::Receipt(Receipt::Training(Native::Pending)))
            | Err(Stage::Receipt(Receipt::Owner(Owner::Pending)))
            | Err(Stage::Training(Native::Store(Store::Missing)))
            | Err(Stage::Receipt(Receipt::Training(Native::Store(Store::Missing))))
            | Err(Stage::Receipt(Receipt::Owner(Owner::Store(Store::Missing)))) => {
                return Ok(None);
            }
            Err(error) => return Err(error.into()),
        };
        // The original material lane has re-read both original owners and the
        // live source before and after its work. Authenticate those exact
        // retained bytes with the original command context and current time.
        let original = wire::authenticate_receipt(
            &self.context,
            material.receipt().clone(),
            material.attestation().clone(),
            super::super::now()?,
        )?;
        Ok(Some(original))
    }
}

#[path = "cell_q24_training_shared_readback_test_support.rs"]
pub(crate) mod shared_readback;

//! Consume one completed original Trainer client into sealed local readback.
//! The original channel, request counter and absolute lifetime stay in place.

use std::sync::Arc;

use super::Error;
use super::OriginalCellQ24TrainingCommandClientV1;
use super::OriginalCellQ24TrainingCommandReceiptV1;
use super::now;
use super::wire;

impl OriginalCellQ24TrainingCommandClientV1 {
    pub(crate) fn seal_original_completed_readback(
        self,
        expected: &OriginalCellQ24TrainingCommandReceiptV1,
    ) -> Result<Arc<Self>, Error> {
        let retained = self.retained.try_lock().map_err(|_| Error::Unavailable)?;
        let original = retained.as_ref().ok_or(Error::ReadbackRequired)?;
        if original != expected {
            return Err(Error::Binding("same completed original Trainer before sharing"));
        }
        let mut slot = self.channel.try_lock().map_err(|_| Error::Unavailable)?;
        let channel = slot.as_mut().ok_or(Error::Unavailable)?;
        channel.peer.check_peer_lifetime()?;
        let authenticated = wire::authenticate_receipt(
            &self.context,
            original.receipt().clone(),
            original.attestation().clone(),
            now()?,
        )?;
        if &authenticated != original {
            return Err(Error::Binding("full original Trainer signature before sharing"));
        }
        // This is a one-way attenuation of the same client, not a new channel.
        channel.execution_requested = true;
        drop(slot);
        drop(retained);
        Ok(Arc::new(self))
    }
}

