                // replaced; pause before calling the real E dispatch.
                if published_e_reads == 2 {
                    reached_tx
                        .take()
                        .context("one original late E boundary")?
                        .send(())
                        .map_err(|_| anyhow::anyhow!("fixture observer dropped"))?;
