        Version::fixture_read_bound_original_version(Arc::clone(&host)).await,
        Err(VersionError::CommitUncertain)
    ));
    let context = crate::OriginalCircuitEvaluatedLearningReadContextV1::for_original_selection(
        f.readback_context()?,
    )?;
    let (reader, channel) =
        crate::circuit_feature_current::original_learning_read_fixture::evaluated_client(context)?;
    let server = tokio::spawn(Version::fixture_serve_original_selection_channel(
        Arc::clone(&host),
        channel,
    ));
    assert!(reader.read_current().await.is_err());
    server.abort();
    assert!(
        server
            .await
            .expect_err("unready serving lane cancelled")
            .is_cancelled()
    );
    drop(reader);
    assert!(
        Version::run_original_c(Arc::clone(&host), codex_arg0::Arg0DispatchPaths::default())
            .await
            .is_err()
    );
    assert!(
        Version::prepare_original_version_fixture(Arc::clone(&host))
