async fn reject_changed_expected_signature(index: usize) -> anyhow::Result<()> {
    let case = Box::pin(ExportCase::ready(Some(index))).await?;
    let result: anyhow::Result<()> = async {
        let host = case.host()?;
        let before = case.original_bytes()?;
        anyhow::ensure!(matches!(
            Version::share_original_evaluated_readbacks(Arc::clone(&host)).await,
            Err(VersionError::Binding("same original complete cold E/D/T checkpoint"))
        ), "the complete original signature, not only receipt fields, must match");
        anyhow::ensure!(!host.fixture_original_selection_reader_installed()?, "wrong original signature cannot admit a reader");
        anyhow::ensure!(case.original_bytes()? == before, "bad expected bytes cannot rewrite original evidence");
        anyhow::ensure!(case.cell_has_no_additional_transition()?, "no additional C Cell transition");
        Ok(())
    }.await;
    finish_case(result, case).await
}

